function dft(re, im){ var N=re.length; var ore=[], oim=[];
  for(var k=0;k<N;k++){ var sr=0, si=0;
    for(var n=0;n<N;n++){ var ang=-2*Math.PI*k*n/N;
      sr += re[n]*Math.cos(ang) - im[n]*Math.sin(ang);
      si += re[n]*Math.sin(ang) + im[n]*Math.cos(ang); }
    ore.push(sr); oim.push(si); }
  return {re:ore, im:oim}; }
function magnitude(re, im){ return Math.sqrt(re*re+im*im); }
var EXPORTS={dft:dft,magnitude:magnitude};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FourierForgePure = EXPORTS; }
